#!/usr/bin/env python3
"""Re-render the original illustration, which was authored in PowerPoint.

The embedded SVG retains vector drawing paths and original illustration assets.
This is an artwork renderer, not a simulation or a reconstruction of the model.
Dependencies: reportlab, svglib. Run: python plot.py
"""
from io import BytesIO
from pathlib import Path

from reportlab.graphics import renderPDF
from reportlab.lib.utils import ImageReader
from reportlab.pdfgen.canvas import Canvas
from svglib.svglib import svg2rlg


class TransparentCanvas(Canvas):
    """Preserve the alpha channels of the embedded illustration assets."""

    def drawInlineImage(self, image, x, y, width=None, height=None, **kwargs):
        return self.drawImage(ImageReader(image), x, y, width, height,
                              mask="auto", **kwargs)


def main():
    drawing = svg2rlg(BytesIO(ARTWORK_SVG.encode("utf-8")))
    output = Path(__file__).resolve().with_name("figure2.pdf")
    renderPDF.drawToFile(drawing, str(output), canvasMaker=TransparentCanvas)
    print(output)


